use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let mut result = String::new();
    if let Value::Array(arr) = input {
        for &byte in arr.iter().filter_map(|v| v.as_u64().map(|v| v as u8)) {
            let hex_digit1 = ((byte >> 4) & 0x0F) as u8 as char;
            let hex_digit2 = (byte & 0x0F) as u8 as char;
            result.push(hex_digit1 as char);
            result.push(hex_digit2 as char);
        }
    }
    Value::String(result)
}
